{$ param title label="Title" default="Note" description="Heading shown at the top of the box." $}
{$ param variant label="Variant" default="info" description="info, tip, or warn." $}

<div class="ss-message border p-4 mb-8 border-line-blue bg-bg-blue ss-message-{$= variant $}">
  <h3 class="ss-small">{$= title $}</h3>
  {$ slot body $}
    <p class="ss-small">Message body.</p>
  {$ /slot $}
</div>
